package com.mst.repositories;import com.mst.models.UserAccount;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="sale.live",matches="true") class SaleGdnPurchaseReturnLiveTest{static JdbcTemplate jdbc()throws Exception{var p=new Properties();try(var in=Files.newInputStream(Path.of("src/main/resources/application.properties"))){p.load(in);}var j=new JdbcTemplate(new DriverManagerDataSource(p.getProperty("spring.datasource.url"),p.getProperty("spring.datasource.username"),p.getProperty("spring.datasource.password")));j.setQueryTimeout(90);return j;}static int n(Object o){return ((Number)o).intValue();}@Test void desktopLookupsHistoryAndReadMatchGoldenAce()throws Exception{var j=jdbc();var a=j.queryForMap("SELECT ID,OrganizationId,CompanyId,BranchesId,AppId FROM UserAccount WHERE UserName='numan'");var u=new UserAccount();u.setId(n(a.get("ID")));u.setOrganizationId(n(a.get("OrganizationId")));u.setCompanyId(n(a.get("CompanyId")));u.setBranchesId(n(a.get("BranchesId")));u.setAppId(n(a.get("AppId")));var r=new SaleGdnPurchaseReturnRepository(j);var initial=r.initial(u,58);assertFalse(((List<?>)initial.get("suppliers")).isEmpty(),"supplier lookup is empty");assertFalse(((List<?>)initial.get("cities")).isEmpty(),"city lookup is empty");var history=r.history(u,58);if(!history.isEmpty()){var record=r.record(u,n(history.get(0).get("Id")));assertEquals(703,n(record.get("DocumentTypeId")));assertTrue(record.containsKey("details"));}Files.createDirectories(Path.of("migration/sale/evidence"));Files.writeString(Path.of("migration/sale/evidence/gdn-purchase-return-read.txt"),"GDN Purchase Return document 703. GoldenAcedb desktop numbering, supplier, pending gate pass, warehouse, crop, job lot, packing type, expense item, city, transporter, feature 5, form history and load paths executed for Numan tenant 78/78 branch 58 year 58. Suppliers="+((List<?>)initial.get("suppliers")).size()+", cities="+((List<?>)initial.get("cities")).size()+", transporters="+((List<?>)initial.get("transporters")).size()+", feature5="+initial.get("feature5")+", pending gate passes="+((List<?>)initial.get("gatePasses")).size()+", history rows="+history.size()+". Runtime CRUD rollback remains pending.\n");}}
